INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- databases/database-design/overview ----------
('databases', 'database-design', 'overview', 'What specific problem does moving from an unnormalized table (e.g. customer name/email repeated on every order row) to 2NF/3NF actually solve?', '["It makes the database file smaller with no other benefit", "It eliminates update, insertion, and deletion anomalies -- e.g. without normalization, changing a customer''s email requires updating every order row that repeated it, or the data becomes inconsistent between rows", "It removes the need for primary keys", "It is purely a stylistic convention with no functional effect on query correctness"]', 1, 'Each normal form targets a specific anomaly -- being able to name which anomaly a given normalization step prevents is what separates real understanding from memorizing the rule definitions.', 'beginner'),
('databases', 'database-design', 'overview', 'In a classic one-to-many relationship like Customer to Orders, why is a junction table NOT needed, unlike a many-to-many relationship?', '["Junction tables are never needed in any relational design", "A one-to-many relationship can be represented with a single foreign key on the \"many\" side (orders.customer_id) pointing back to the \"one\" side -- a junction table is only necessary for many-to-many relationships, where a single foreign key on either table can''t represent multiple associations per row on both sides", "One-to-many relationships require two separate foreign keys instead", "Junction tables are only used for one-to-one relationships"]', 1, 'A foreign key column is sufficient to express one-to-many because each \"many\" row only ever needs to reference exactly one \"one\" row -- many-to-many needs the extra junction table specifically because both sides can have multiple associations.', 'beginner'),
('databases', 'database-design', 'overview', 'Why does column order matter in a composite index like `(customer_id, status)`?', '["It doesn''t matter -- composite indexes work identically regardless of column order", "The index is physically structured to search efficiently by its leftmost column first, then narrow within that -- this composite index serves queries filtering on customer_id alone or customer_id AND status together efficiently, but not a query filtering on status alone", "Column order only matters for indexes with more than 3 columns", "Reversing the column order only affects INSERT performance, not SELECT performance"]', 1, 'This is the leftmost-prefix rule -- a foundational fact about how composite B-tree indexes are structured, which is why the highest-selectivity equality-condition column is conventionally placed first.', 'intermediate'),
('databases', 'database-design', 'overview', 'What does a partial index like `CREATE INDEX idx_active_orders ON orders(created_at) WHERE status = ''active''` accomplish that a full index on the same column wouldn''t?', '["Nothing -- WHERE clauses are ignored when creating an index", "It only indexes rows matching the condition, making the index smaller and faster specifically for queries that also filter on that same condition -- useful when a query pattern consistently targets a well-defined subset of rows", "It automatically deletes rows not matching the condition", "It forces every query against the table to include that WHERE condition"]', 1, 'Partial indexes are a genuine size/performance win when queries consistently target a small, well-defined subset of a table -- indexing only that subset avoids the overhead of indexing rows that will never be searched that way.', 'intermediate'),
('databases', 'database-design', 'overview', 'Under the CAP theorem''s common framing, why is it said that "P is required, so you choose between C and A"?', '["Because Partition tolerance is optional and can simply be disabled", "Because any real distributed system must handle network partitions (they will eventually happen), so the meaningful design choice is which of Consistency or Availability to prioritize when a partition actually occurs, not whether to accept Partition tolerance at all", "Because Consistency and Availability are always achievable simultaneously with enough hardware", "Because CAP theorem only applies to single-node databases, not distributed ones"]', 1, 'Network partitions are treated as an unavoidable reality of distributed systems, not a choice -- so CAP is really framed as a forced tradeoff between C and A specifically during a partition event.', 'intermediate'),

-- ---------- databases/database-design/fundamentals ----------
('databases', 'database-design', 'fundamentals', 'What is the practical tradeoff between a natural key (e.g. an email address) and a surrogate key (e.g. an auto-incrementing integer) as a primary key?', '["Natural keys are always faster to query than surrogate keys", "A natural key can change (an email gets updated) or turn out not to be as unique as assumed, and changing a primary key is disruptive since every foreign key referencing it must cascade -- a surrogate key avoids this because it never carries business meaning that could change", "Surrogate keys cannot be indexed", "There is no real difference -- the choice is purely aesthetic"]', 1, 'This is why surrogate keys are the common default -- they''re specifically designed to never need to change for business reasons, sidestepping the disruption a changing natural key would cause to every referencing foreign key.', 'beginner'),
('databases', 'database-design', 'fundamentals', 'What is the actual difference between `ON DELETE RESTRICT` and `ON DELETE CASCADE` on a foreign key?', '["They behave identically -- the names are just historical aliases", "RESTRICT blocks the delete of a parent row if any referencing child rows exist, forcing an explicit decision about what to do with them; CASCADE automatically deletes those child rows too when the parent is deleted", "CASCADE is always the safer default because it keeps the database clean", "RESTRICT only applies to UPDATE statements, not DELETE"]', 1, 'RESTRICT is generally the safer default for most real systems specifically because it forces an explicit decision rather than silently deleting potentially far more data than the person running the DELETE anticipated.', 'beginner'),
('databases', 'database-design', 'fundamentals', 'Why does a foreign key constraint provide a stronger guarantee than an equivalent check written only in application code?', '["Application-level checks are always faster than database-level constraints", "A foreign key is enforced unconditionally by the database itself regardless of what any application code does or doesn''t check -- it still protects against a direct database script, a bug in application validation, or a different service writing to the same table that the application-level check was never designed to cover", "Foreign keys can be bypassed just as easily as application code checks", "Application code checks are more reliable because they run before the database ever sees the write"]', 1, 'This is the core value of a database-level constraint: it doesn''t depend on every possible writer to the table behaving correctly, unlike a check that only exists in one application''s code path.', 'intermediate'),
('databases', 'database-design', 'fundamentals', 'What is the real cost of adding an index that isn''t accounted for by "indexes only help performance"?', '["Indexes have no real cost -- more indexes are always strictly better", "Every index speeds up the reads it''s designed for, but also slows down every INSERT/UPDATE/DELETE on that table (since each write has to update the index too) and consumes real storage space", "Indexes only cost storage space, never affecting write performance", "The cost of an index only matters for tables with fewer than 1000 rows"]', 1, 'This read/write tradeoff is why "just add an index" isn''t universally correct advice -- an index on a rarely-queried column, or on a heavily-written table where the read pattern doesn''t benefit, is a real ongoing cost with no corresponding benefit.', 'intermediate'),
('databases', 'database-design', 'fundamentals', 'Given a table `orders(order_id, customer_name, customer_email, product1, product2, product3)`, which specific problem does 1NF (atomic values, no repeating groups) directly fix?', '["It fixes slow query performance on large tables", "It fixes the repeating group problem -- storing product1/product2/product3 as separate columns (rather than one row per product) forces an awkward, non-scalable structure and makes querying \"all products in this order\" structurally difficult", "It fixes foreign key constraint violations", "It fixes the need for a primary key entirely"]', 1, 'The product1/product2/product3 pattern is a classic 1NF violation -- fixing it means moving to one row per product (a separate order_items table), which is exactly what makes the data atomic and queryable without schema-level guessing about how many products a single order might have.', 'intermediate'),

-- ---------- databases/database-design/intermediate ----------
('databases', 'database-design', 'intermediate', 'What makes denormalization a "deliberate" decision rather than just skipping normalization?', '["There is no real difference -- denormalized and unnormalized schemas are the same thing", "Denormalization is applied with a clear understanding of the specific query it''s optimizing for and the specific update-anomaly risk being accepted in exchange -- a schema that''s simply unnormalized because normalization was never done lacks that reasoning entirely", "Denormalization requires removing all foreign keys from the schema", "Denormalization can only be applied to NoSQL databases, not relational ones"]', 1, 'The distinction matters because denormalization done well is a measured tradeoff for a specific, identified hot path -- not a default posture or a shortcut taken without understanding what integrity guarantee is being given up.', 'intermediate'),
('databases', 'database-design', 'intermediate', 'When is seeing `Seq Scan` in an `EXPLAIN ANALYZE` output NOT actually a performance problem?', '["Seq Scan is always a problem and should always be eliminated", "For a small table, or a query returning a large fraction of the table''s rows, a sequential scan can genuinely be faster than an index scan, since index lookups carry their own per-row overhead that a full sequential read of a small/mostly-matching table can beat", "Seq Scan only appears in query plans for INSERT statements, never SELECT", "Seq Scan indicates the table has no primary key defined"]', 1, 'The more useful intermediate skill isn''t reflexively treating every Seq Scan as bad -- it''s recognizing when an index scan SHOULD be happening (large table, highly selective filter) but isn''t, which is the actual signal worth investigating.', 'intermediate'),
('databases', 'database-design', 'intermediate', 'Why might a many-to-many junction table need to become a "richer entity" rather than staying a bare two-column link table?', '["Junction tables are never allowed to have more than two columns", "Real many-to-many relationships often carry relationship-specific data -- e.g. an enrollments row might need a grade, completion_status, or enrolled_by, which belongs to the relationship between a student and a course, not to either entity alone", "Adding extra columns to a junction table always violates 3NF", "This only applies to NoSQL document databases, not relational schemas"]', 1, 'Recognizing when a junction table needs additional columns to hold data that genuinely belongs to the relationship itself, rather than forcing that data awkwardly into one of the two related entities, is a real intermediate design judgment call.', 'intermediate'),
('databases', 'database-design', 'intermediate', 'What concrete design-level benefit does a schema migration tool (Flyway, Alembic, Prisma Migrate) provide over manual, ad hoc `ALTER TABLE` statements run directly against production?', '["Migration tools automatically optimize query performance", "Migration tools make every schema change reviewable (a migration file in a pull request), reproducible across environments (dev/staging/production apply the same ordered migrations), and reversible where rollback is supported -- none of which is true for undocumented manual changes made directly against a live database", "Migration tools eliminate the need for foreign key constraints", "Migration tools are only useful for NoSQL databases, not relational ones"]', 1, 'The core value is treating schema evolution with the same discipline as application code changes -- reviewable, reproducible, and (where supported) reversible -- rather than relying on manual, undocumented database surgery.', 'intermediate'),
('databases', 'database-design', 'intermediate', 'Why is composite index column order described as "not arbitrary" -- what specifically breaks if the order is wrong for a given query pattern?', '["Nothing breaks -- any column order works for any query with equal performance", "A composite index (customer_id, status) is structured so customer_id narrows the search first and status narrows within that already-narrowed set -- a query filtering only on status can''t efficiently use this index, since the index isn''t organized to search by status independently of customer_id", "Column order only affects how the index displays in admin tools, not actual query performance", "Reordering columns in a composite index requires recreating every other index on the table"]', 1, 'This is the leftmost-prefix rule in concrete terms -- the general guidance (equality condition with higher selectivity first, range conditions or lower-selectivity columns after) follows directly from how the index is physically structured to search.', 'advanced'),

-- ---------- databases/database-design/advanced ----------
('databases', 'database-design', 'advanced', 'What is the key structural difference between table partitioning and sharding?', '["They are two names for exactly the same technique", "Partitioning splits a table into smaller physical pieces within a single database instance while still presenting one logical table to queries; sharding splits data across multiple, separate database instances/servers entirely -- necessary once a single instance''s write throughput or storage genuinely can''t scale further vertically", "Sharding only applies to NoSQL databases, never relational ones", "Partitioning requires more application-level code changes than sharding"]', 1, 'This distinction matters because sharding is a much bigger architectural commitment than partitioning -- cross-shard joins are expensive and the shard-key choice is hard to change later, so it shouldn''t be adopted before partitioning within a single instance is no longer sufficient.', 'advanced'),
('databases', 'database-design', 'advanced', 'In multi-tenant schema design, why is row-level security (RLS) considered a meaningfully stronger safeguard than relying solely on application-code discipline for a shared-table (`tenant_id` column) approach?', '["RLS makes the tenant_id column unnecessary", "Application-code discipline depends on every single query correctly including a WHERE tenant_id = ? filter -- a missed filter is a serious cross-tenant data leak; RLS enforces the isolation at the database level itself, so even a query that forgets the filter is still restricted by the database, not just by hoping every developer remembered", "RLS is only available in NoSQL databases", "RLS eliminates the need for any tenant isolation testing"]', 1, 'The core argument for RLS in this context mirrors the foreign-key-vs-application-check argument elsewhere in this course: a database-enforced guarantee doesn''t depend on every writer/query behaving correctly, unlike a convention that lives only in application code.', 'advanced'),
('databases', 'database-design', 'advanced', 'What real design implication follows from read replicas being asynchronously replicated rather than synchronously updated?', '["Read replicas always return identical data to the primary with zero delay", "A write followed immediately by a read from a replica can return stale data due to replication lag -- the design question is which specific reads can tolerate that lag (most analytics/reporting queries can) versus which need the just-written data and should read from the primary or use a \"read your own writes\" pattern instead", "Asynchronous replication means replicas never need to be trusted for any read at all", "Replication lag only affects write performance, never read correctness"]', 1, 'This is the practical tradeoff that trips people up: read replicas solve read-scaling but introduce a real consistency question that has to be deliberately designed around per read pattern, not assumed away.', 'advanced'),
('databases', 'database-design', 'advanced', 'What does event sourcing (storing every state change as an immutable, append-only event) trade away, and what does it gain in return, compared to traditional "store current state, overwrite on update" design?', '["It trades away all query performance with no benefit", "It trades the simplicity of straightforward update-in-place design for a genuine audit trail (every historical state is preserved) and the ability to rebuild derived views from scratch by replaying history -- valuable when audit requirements or the need to add new derived views later outweigh the added design/storage complexity", "It eliminates the need for a database entirely", "It is only applicable to NoSQL document databases"]', 1, 'Event sourcing is a genuine architectural tradeoff, not a strictly superior approach -- it''s worth adopting specifically when audit/history requirements or evolving derived-view needs justify the real complexity it adds.', 'advanced'),
('databases', 'database-design', 'advanced', 'Why is a poorly chosen shard key described as potentially creating "hot shards"?', '["Hot shards refer to physical server temperature issues unrelated to data distribution", "If the shard key doesn''t distribute data and traffic evenly across shards, one shard can end up receiving disproportionate load (storage and/or query traffic) while others sit comparatively idle -- an uneven, hard-to-rebalance distribution problem", "Hot shards only occur when using range partitioning, never hash-based sharding", "Choosing any shard key guarantees perfectly even distribution automatically"]', 1, 'This is exactly why shard-key selection is called a hard, unavoidable design decision -- a bad choice doesn''t just cause a minor inefficiency, it can concentrate load onto one shard in a way that''s expensive to correct after the fact, since the shard key is hard to change later.', 'advanced');
